    "name": "AW SmoothEQ3",
    "type": "Pedals",
    "category": "EQ",
    "engine": "Airwindows",
    "detail": "EQ · Airwindows",
    "description": "SmoothEQ3 is the most approachable EQ.",
    "source": "https://github.com/baconpaul/airwin2rack/blob/b6eef0af60cd32641b09837096e41bbcdb030341/res/awpdoc/SmoothEQ3.txt",
    "icon": "≋",
