    "name": "AW Remap",
    "type": "Pedals",
    "category": "Studio",
    "engine": "Airwindows",
    "detail": "Studio · Airwindows",
    "description": "Remap puts the guts back into overloudenated audio!",
    "source": "https://github.com/baconpaul/airwin2rack/blob/b6eef0af60cd32641b09837096e41bbcdb030341/res/awpdoc/Remap.txt",
    "icon": "◈",
