    "engine": "Airwindows",
    "detail": "Lo-fi · Airwindows",
    "description": "Dubly3 refines and transforms the Dubly sound.",
    "source": "https://github.com/baconpaul/airwin2rack/blob/b6eef0af60cd32641b09837096e41bbcdb030341/res/awpdoc/Dubly3.txt",
    "icon": "◈",
    "colour": "#c28e7c",
